var setup=UnityEngine.Object.FindFirstObjectByType<QuickSetup>();var p=setup.playerModelPrefab;var anim=p.GetComponentInChildren<UnityEngine.Animator>(true);var text=new System.Text.StringBuilder();text.AppendLine("Prefab="+UnityEditor.AssetDatabase.GetAssetPath(p)+" Controller="+UnityEditor.AssetDatabase.GetAssetPath(anim.runtimeAnimatorController));
foreach(var path in new[]{"Assets/UnityChan/Animations/unitychan_DAMAGED00.fbx","Assets/UnityChan/Animations/unitychan_DAMAGED01.fbx"})foreach(var a in UnityEditor.AssetDatabase.LoadAllAssetsAtPath(path))if(a is UnityEngine.AnimationClip c&&!c.name.StartsWith("__"))text.AppendLine(path+" clip="+c.name+" length="+c.length+" human="+c.humanMotion+" loop="+c.isLooping);
var controller=anim.runtimeAnimatorController as UnityEditor.Animations.AnimatorController;foreach(var layer in controller.layers){text.AppendLine("Layer="+layer.name);foreach(var s in layer.stateMachine.states)text.AppendLine("State="+s.state.name+" motion="+(s.state.motion!=null?s.state.motion.name:"null"));}foreach(var param in controller.parameters)text.AppendLine(param.name+" "+param.type);
return text.ToString();
